(function(root){
 const languages={KR:['한국어','Korean','KO'],EN:['영어','English','ETC'],KH:['크메르어','Cambodia','Khmer','KM'],NP:['네팔어','Nepal','Nepali','NE'],PH:['필리핀어','Philippines','Filipino','Tagalog'],ID:['인도네시아어','Indonesia','Indonesian'],VN:['베트남어','Vietnam','Vietnamese','VI'],CN:['중국어 간체','Chinese','ZH-CN'],TW:['중국어 번체','ZH-TW'],JP:['일본어','Japanese','JA'],RU:['러시아어','Russian'],UZ:['우즈베크어','Uzbek'],MM:['미얀마어','Myanmar','Burmese','MY'],BD:['벵골어','Bangladesh','Bengali','BN'],TH:['태국어','Thai'],LA:['라오스어','Lao'],LK:['싱할라어','Sinhala'],PK:['우르두어','Urdu'],MN:['몽골어','Mongolian']};
 const norm=v=>String(v??'').normalize('NFC').replace(/\s+/g,' ').trim();
 const code=v=>{const n=norm(v).toLowerCase();return Object.keys(languages).find(k=>[k,...languages[k]].some(x=>x.toLowerCase()===n))};
 function parse(matrix){
  let header=-1,best=1;matrix.slice(0,50).forEach((r,i)=>{const score=r.filter(v=>code(v)).length;if(score>best){header=i;best=score}});
  if(header<0)throw Error('언어 열을 찾지 못했습니다. KR, EN(또는 ETC), KH 등의 열 제목이 있는 시트를 선택하세요.');
  const columns=matrix[header].map((v,index)=>({code:code(v),index})).filter(c=>c.code);
  if(new Set(columns.map(c=>c.code)).size!==columns.length)throw Error('같은 언어 열이 중복되어 있습니다. 사용할 열만 남겨 주세요.');
  const keyIndex=matrix[header].findIndex(v=>/^(key|키)$/i.test(norm(v)));const rows=[];for(let i=header+1;i<matrix.length;i++){const row=matrix[i];if(columns.filter(c=>code(row[c.index])===c.code).length>=2)continue;if(!columns.some(c=>norm(row[c.index])))continue;const values={};columns.forEach(c=>values[c.code]=String(row[c.index]??''));rows.push({number:i+1,key:keyIndex>=0?norm(row[keyIndex]):'',values})}
  return {columns,rows};
 }
 const matches=(text,rows,source)=>rows.filter(r=>norm(r.values[source])===norm(text)&&norm(text));
 function bind({host,getSvg,commit,select,message}){
  const section=document.createElement('section');section.className='sv-translations';section.innerHTML='<h3>엑셀 번역 적용</h3><p>번역된 문구를 그대로 사용합니다. KR 원문과 디자인 문구를 연결하세요.</p><button data-upload>번역 Excel 업로드</button><input data-file type="file" accept=".xlsx,.csv" hidden aria-label="번역 Excel 파일"><div data-options hidden><label>시트<select data-sheet aria-label="번역 시트"></select></label><label>원문 언어<select data-source aria-label="원문 언어"></select></label><label>적용 언어<select data-language aria-label="적용 언어"></select></label><p data-summary role="status"></p><details><summary>문구 연결 확인·수정</summary><div data-mappings></div></details><label><input type="checkbox" data-fit checked> 원래 문구 너비에 맞춰 축소</label><button data-apply>선택 언어 적용</button><button data-original>업로드 전 문구 복원</button><p>빈 번역은 원문을 유지합니다. 적용 후 글꼴·줄바꿈을 검수하고 저장하세요. 새로고침하면 번역표는 다시 업로드해야 합니다.</p></div><p data-error role="alert"></p>';
  host.prepend(section);const shortcut=document.createElement('button');shortcut.textContent='번역 Excel 업로드';shortcut.className='sv-translation-shortcut';document.querySelector('.sv-editor header')?.append(shortcut);shortcut.onclick=()=>section.querySelector('[data-file]').click();const q=s=>section.querySelector(s);let book,table,originals=[],bindings=[],fileName='';
  const textNodes=()=>[...getSvg().querySelectorAll('text')].filter(n=>!n.closest('defs,clipPath,mask'));
  const option=(value,label)=>{const o=document.createElement('option');o.value=value;o.textContent=label;return o};
  function capture(){originals=textNodes().map((node,i)=>({text:node.textContent,width:node.getBBox().width,markup:node.cloneNode(true),id:node.id,index:i}));}
  function map(){bindings=originals.map(o=>{const found=matches(o.text,table.rows,q('[data-source]').value);return found.length===1?found[0].number:null});renderMappings()}
  function renderMappings(){const target=q('[data-mappings]');target.replaceChildren();originals.forEach((o,i)=>{const label=document.createElement('label'),span=document.createElement('span');span.textContent=o.text;label.append(span);const input=document.createElement('select');input.setAttribute('aria-label','문구 '+(i+1)+' 번역 연결');input.append(option('',matches(o.text,table.rows,q('[data-source]').value).length>1?'중복 원문 · 행 선택':'변경하지 않음'));for(const row of table.rows)if(norm(row.values[q('[data-source]').value]))input.append(option(row.number,row.number+'행 · '+row.values[q('[data-source]').value].slice(0,70)));input.value=bindings[i]||'';input.onchange=()=>{bindings[i]=+input.value||null;summary()};label.append(input);target.append(label)});summary()}
  function summary(){const selected=q('[data-language]').value,linked=bindings.filter(Boolean).length,missing=bindings.filter(n=>n&&!norm(table.rows.find(r=>r.number===n)?.values[selected])).length;q('[data-summary]').textContent=fileName+' · 연결 '+linked+'/'+originals.length+'개 · 빈 번역 '+missing+'개';}
  function sheet(){try{const matrix=root.XLSX.utils.sheet_to_json(book.Sheets[q('[data-sheet]').value],{header:1,defval:'',raw:false});if(matrix.length>=10002)throw Error('10,000행 이하로 나누어 업로드해 주세요.');table=parse(matrix);for(const key of ['data-source','data-language']){q('['+key+']').replaceChildren(...table.columns.map(c=>option(c.code,languages[c.code][0]+' ('+c.code+')')))}q('[data-source]').value=table.columns.some(c=>c.code==='KR')?'KR':table.columns[0].code;q('[data-language]').value=table.columns.find(c=>c.code!==q('[data-source]').value)?.code||table.columns[0].code;map();q('[data-error]').textContent='';q('[data-apply]').disabled=false}catch(e){q('[data-error]').textContent=e.message;q('[data-apply]').disabled=true;}}
  q('[data-upload]').onclick=()=>q('[data-file]').click();q('[data-file]').onchange=async e=>{const file=e.target.files[0];if(!file)return;q('[data-error]').textContent='번역표를 읽는 중…';try{const next=root.XLSX.read(await file.arrayBuffer(),{type:'array',sheetRows:10002,cellHTML:false,cellFormula:false});if(!next.SheetNames.length)throw Error('읽을 수 있는 시트가 없습니다.');book=next;fileName=file.name;capture();q('[data-sheet]').replaceChildren(...book.SheetNames.map(n=>option(n,n)));q('[data-options]').hidden=false;sheet();}catch(err){q('[data-error]').textContent=err.message||'엑셀 파일을 읽지 못했습니다.'}e.target.value=''};
  q('[data-sheet]').onchange=sheet;q('[data-source]').onchange=map;q('[data-language]').onchange=summary;
  function checkNodes(){const nodes=textNodes();if(nodes.length!==originals.length||nodes.some((n,i)=>n.id!==originals[i].id))throw Error('디자인의 텍스트 요소가 바뀌었습니다. 번역 파일을 다시 업로드해 연결해 주세요.');return nodes}
  function replace(node,value){const first=node.querySelector('tspan');for(const a of ['x','y'])if(first?.hasAttribute(a)&&!node.hasAttribute(a))node.setAttribute(a,first.getAttribute(a));const x=node.getAttribute('x')||'0';node.replaceChildren();String(value).split(/\r?\n/).forEach((line,i)=>{const t=document.createElementNS('http://www.w3.org/2000/svg','tspan');t.setAttribute('x',x);t.setAttribute('dy',i?'1.25em':'0');t.textContent=line;node.append(t)});}
  q('[data-apply]').onclick=()=>{try{const nodes=checkNodes(),lang=q('[data-language]').value;let applied=0,shrunk=0;nodes.forEach((node,i)=>{const o=originals[i],row=table.rows.find(r=>r.number===bindings[i]);if(!row)return;const value=row.values[lang];for(const attr of ['font-size','x','y']){const prior=o.markup.getAttribute(attr);if(prior!==null)node.setAttribute(attr,prior);else node.removeAttribute(attr);}if(!norm(value)){node.replaceChildren(...[...o.markup.childNodes].map(n=>n.cloneNode(true)));return}replace(node,value);if(q('[data-fit]').checked&&o.width>0){const width=node.getBBox().width;if(width>o.width){const fs=parseFloat(getComputedStyle(node).fontSize);node.setAttribute('font-size',Math.max(1,fs*o.width/width));shrunk++}}applied++});select(null);commit();message(languages[lang][0]+' '+applied+'개 적용 · 축소 '+shrunk+'개 · 저장 전 검수해 주세요.');q('[data-error]').textContent='';}catch(e){q('[data-error]').textContent=e.message}};
  q('[data-original]').onclick=()=>{try{const nodes=checkNodes();nodes.forEach((node,i)=>{const original=originals[i].markup;node.replaceChildren(...[...original.childNodes].map(n=>n.cloneNode(true)));for(const a of ['x','y','font-size']){if(original.hasAttribute(a))node.setAttribute(a,original.getAttribute(a));else node.removeAttribute(a)}});select(null);commit();message('업로드 전 문구를 복원했습니다.')}catch(e){q('[data-error]').textContent=e.message}};
 }
 const api={parse,matches,languages,norm,bind};if(typeof module!=='undefined')module.exports=api;else root.HanpassSvgTranslations=api;
})(typeof window!=='undefined'?window:globalThis);
